// Each message here is one entry of the batch, carrying its own
// msg.dapr.entryId and msg.dapr.ackId - keep msg.dapr intact.
if (!msg.payload || typeof msg.payload.orderId === 'undefined') {
    msg.ackStatus = 'DROP'; // malformed - never retry it
} else if (msg.payload.status === 'pending') {
    msg.ackStatus = 'RETRY'; // upstream isn't ready yet - ask Dapr to redeliver
} else {
    msg.ackStatus = 'SUCCESS';
}
return msg;
